import{_ as t,o as a,c as o,ae as n}from"./chunks/framework.DQC_QtFV.js";const u=JSON.parse('{"title":"Console overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/console/index.md","filePath":"en/guide/console/index.md","lastUpdated":1793162416000}'),s={name:"en/guide/console/index.md"};function i(r,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="console-overview" tabindex="-1">Console overview <a class="header-anchor" href="#console-overview" aria-label="Permalink to &quot;Console overview&quot;">​</a></h1><p>The console is this machine&#39;s panel: <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a>, signed in with <code>CONSOLE_PASSWORD</code>, one session cookie, and nothing works before login. It is the only service meant to be published, and the only one that needs to be.</p><p>The left nav has four groups, one topic each - everything about one feature lives on its own page:</p><table tabindex="0"><thead><tr><th>Group</th><th>Pages</th></tr></thead><tbody><tr><td>运行</td><td>概览, QQ</td></tr><tr><td>机器人</td><td>会话, 人设, 记忆, 表情包, 定时</td></tr><tr><td>设置</td><td>模型, 安全, 工作区, 高级</td></tr><tr><td>—</td><td>日志, 退出登录</td></tr></tbody></table><p>The status block sits at the top of the nav: QQ login, the database key, the bot and Jev lights, the window token gauge, and pause / resume.</p><h2 id="概览-the-page-to-open-first" tabindex="-1">概览: the page to open first <a class="header-anchor" href="#概览-the-page-to-open-first" aria-label="Permalink to &quot;概览: the page to open first&quot;">​</a></h2><p>待处理 lists only problems - QQ not logged in, the key not ok, no main model, Jev missing or unreachable, an empty allow list, an allowed conversation outside the driver scope, the bot paused, a failed skill update - each with the one button that fixes it, and it disappears when there is nothing to report. An empty one is the good state.</p><p>Below it: three summary cards (QQ, 机器人, 会话) and 最近动态, the last five turn, send and join-in entries.</p><h2 id="qq-connection-and-live-view" tabindex="-1">QQ: connection and live view <a class="header-anchor" href="#qq-connection-and-live-view" aria-label="Permalink to &quot;QQ: connection and live view&quot;">​</a></h2><p>The 连接 card is one row per status: whether the client runs, its login state, version, the database key (ok / missing / invalid, with re-extract steps when it is not ok), the last sync time and the mirror lag. The 登录 button below is the manual retry - after a restart the driver clicks it by itself.</p><p>实时画面 is the client&#39;s own framebuffer, proxied out through the console, so VNC is never exposed. The QR scan happens here; the screen is drawn at 1:1 framebuffer pixels inside a frame that scrolls, and 适应窗口 switches to whole-screen scaling. The size is set by <code>SCREEN_W</code> x <code>SCREEN_H</code> (see <a href="./../env.html">Environment variables</a>).</p><h2 id="how-the-pages-read" tabindex="-1">How the pages read <a class="header-anchor" href="#how-the-pages-read" aria-label="Permalink to &quot;How the pages read&quot;">​</a></h2><p>The panel is deliberately simple: a personal assistant on a secondary account, so it has no users, roles or multi-account switching. Each page shows its current value in one line with the action that changes it, and the form lives in a popover, modal or drawer rather than a long flat list. Raw ids, refs and secondary fields sit behind a popover or a 详情 disclosure, always one click away and copyable.</p>',13)])])}const v=t(s,[["render",i]]);export{u as __pageData,v as default};
